function pieceDown(e,id){e.preventDefault();e.stopPropagation();const p=state.pieces.find(x=>x.id===id);if(!p)return;state.selected=id;const el=e.currentTarget,canvas=el.parentElement,r=canvas.getBoundingClientRect();state.drag={id,ox:e.clientX,oy:e.clientY,startX:p.x,startY:p.y,w:r.width,h:r.height};el.setPointerCapture?.(e.pointerId);el.onpointermove=ev=>{if(!state.drag)return;const dx=(ev.clientX-state.drag.ox)/state.drag.w*100,dy=(ev.clientY-state.drag.oy)/state.drag.h*100;p.x=Math.max(0,Math.min(100,state.drag.startX+dx));p.y=Math.max(0,Math.min(100,state.drag.startY+dy));el.style.left=p.x+'%';el.style.top=p.y+'%'};el.onpointerup=()=>{state.drag=null;el.onpointermove=null;el.onpointerup=null;syncCollage();render(true)}}
function rotate(d){const p=state.pieces.find(x=>x.id===state.selected);if(p){p.rotation=(p.rotation||0)+d;syncCollage();render(true)}}function flip(axis){const p=state.pieces.find(x=>x.id===state.selected);if(p){const k=axis==='x'?'flipX':'flipY';p[k]=!p[k];syncCollage();render(true)}}function layer(d){const p=state.pieces.find(x=>x.id===state.selected);if(!p)return;const ordered=[...state.pieces].sort((a,b)=>(a.z||0)-(b.z||0));const idx=ordered.findIndex(x=>x.id===p.id);const target=Math.max(0,Math.min(ordered.length-1,idx+d));if(target===idx)return;const other=ordered[target];const z=p.z||0;p.z=other.z||0;other.z=z;syncCollage();render(true)}
function resizePiece(d){const p=state.pieces.find(x=>x.id===state.selected);if(p){p.w=Math.max(1,Math.min(100,(p.w||24)+d));syncCollage();render(true)}}function syncCollage(){if(state.game?.phase!=='ROUND'||state.game?.submissionStatus?.[state.pid])return;clearTimeout(state.syncTimer);const pieces=state.pieces.map(p=>({...p}));state.syncTimer=setTimeout(()=>{state.syncTimer=null;if(state.game?.phase==='ROUND'&&!state.game?.submissionStatus?.[state.pid])send({type:'SYNC_COLLAGE',pieces:state.pieces.map(p=>({...p}))})},200)}function submitCollage(){
  if(state.game?.phase!=='ROUND'||state.game?.submissionStatus?.[state.pid])return;
  clearTimeout(state.syncTimer);state.syncTimer=null;
  const pieces=state.pieces.map(p=>({...p}));
  if(!send({type:'SUBMIT_COLLAGE',pieces})){
    state.error='Could not submit — connection to the game server was lost.';
    render(true);
  }
}
